// Example catalog, added only when the products table is empty. Replace with your own products.
return [
  { sku: 'WEB-AUDIT', name: 'Website audit', unit: 'each', unit_price: 450 },
  { sku: 'DEV-HOUR', name: 'Development', unit: 'hour', unit_price: 95 },
  { sku: 'DESIGN-HOUR', name: 'Design', unit: 'hour', unit_price: 80 },
  { sku: 'HOSTING-YEAR', name: 'Managed hosting, 12 months', unit: 'year', unit_price: 240 },
  { sku: 'SUPPORT-MONTH', name: 'Support plan', unit: 'month', unit_price: 120 },
].map((p) => ({ json: { ...p, active: true } }));

// Page one is public, so every value is checked here, not only in the browser.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const f = $('Quote Request Form').first().json;
const clean = (v) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
const name = clean(f['Your Name']);
const email = clean(f['Your Email']).toLowerCase();
const company = clean(f['Company']);
const problems = [];
if (!name) problems.push('Your name is empty.');
else if (name.length > 100) problems.push('Your name is longer than 100 characters.');
if (!email) problems.push('Your email is empty.');
else if (email.length > 254 || !/^[^\s@<>(),;:"\[\]\\]+@[^\s@<>(),;:"\[\]\\]+\.[a-z]{2,}$/.test(email)) problems.push('Your email is not a valid address.');
if (!company) problems.push('Company is empty.');
else if (company.length > 100) problems.push('Company is longer than 100 characters.');
return [{ json: { ok: problems.length === 0, customer_name: name, customer_email: email, company, problems,
  page_message: esc(problems.join('\n')) + '\n\nNothing was sent. Please open the form again.' } }];

// Finds the three data tables by exact name (the list also returns similar names) and checks the settings.
const s = $('Quote Settings').first().json;
const listed = $('Find Data Tables').all().map((i) => i.json);
const listError = listed.find((t) => t.error)?.error;
const all = listed.filter((t) => t.id !== undefined);
const problems = [], table_ids = {};
if (listError) problems.push('Listing the data tables failed: ' + String(listError.message ?? listError).slice(0, 300) + '.');
for (const [k, key] of [['products', 'products_table'], ['quotes', 'quotes_table'], ['counter', 'counter_table']]) {
  const name = String(s[key] ?? '').trim();
  const t = all.find((x) => x.name === name);
  if (!name) problems.push(key + ' is empty.');
  else if (!t && !listError) problems.push('Data table "' + name + '" (' + key + ') was not found. Execute "Run Once to Create Tables" or fix the name.');
  else if (t) table_ids[k] = t.id;
}
const str = (k) => String(s[k] ?? '').trim();
const int = (k, lo, hi) => { const v = Number(s[k]); if (str(k) === '' || !Number.isInteger(v) || v < lo || v > hi) problems.push(k + ' must be a whole number from ' + lo + ' to ' + hi + '.'); };
if (!/^[^\s@<>,]+@[^\s@<>,]+\.[^\s@<>,]+$/.test(str('owner_email'))) problems.push('owner_email must be one email address.');
if (!/^([^<>@]*<[^\s@<>,]+@[^\s@<>,]+\.[^\s@<>,]+>|[^\s@<>,]+@[^\s@<>,]+\.[^\s@<>,]+)$/.test(str('from_email'))) problems.push('from_email must be an address or "Name <address>".');
if (!str('business_name')) problems.push('business_name is empty.');
if (!/^[A-Z]{3}$/.test(str('currency'))) problems.push('currency must be a 3-letter code such as EUR.');
const rate = Number(s.tax_rate_percent);
if (str('tax_rate_percent') === '' || !Number.isFinite(rate) || rate < 0 || rate > 100) problems.push('tax_rate_percent must be a number from 0 to 100.');
int('validity_days', 1, 365); int('max_quantity', 1, 100000); int('form_lines', 1, 10);
if (!/^[A-Za-z0-9_-]{0,12}$/.test(str('quote_prefix'))) problems.push('quote_prefix may use up to 12 letters, digits, - or _.');
if (!/^https?:\/\/[^\s]+$/i.test(str('gotenberg_url'))) problems.push('gotenberg_url must start with http:// or https://.');
if (!['a4', 'letter'].includes(str('paper_size').toLowerCase())) problems.push('paper_size must be A4 or Letter.');
if (!/^\d+(\.\d+)?(in|pt|cm)$/.test(str('pdf_margin'))) problems.push('pdf_margin must be a length in in, pt or cm, such as 0.5in or 1cm.');
return [{ json: { setup_ok: problems.length === 0, problems, table_ids } }];

// Builds page two from the active catalog rows. On a retry it shows the problems and keeps the customer's choices.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const s = $('Quote Settings').first().json;
const c = $('Check Customer Details').first().json;
const cur = String(s.currency).trim();
const money = (v) => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const catalog = [];
const read = $('Load Product Catalog').all().map((i) => i.json);
const readError = read.find((r) => r.error)?.error;
for (const r of read.filter((r) => r.id !== undefined)) {
  const sku = String(r.sku ?? '').trim(), name = String(r.name ?? '').replace(/\s+/g, ' ').trim(), unit = String(r.unit ?? '').trim() || 'each';
  const price = Number(r.unit_price);
  if (!sku || !name || r.unit_price === null || r.unit_price === undefined || r.unit_price === '' || !Number.isFinite(price) || price < 0) continue; // incomplete rows are not offered
  const label = name + ' (' + sku + ') - ' + cur + ' ' + money(price) + ' / ' + unit;
  if (!catalog.some((p) => p.label === label)) catalog.push({ sku, name, unit, unit_price: Math.round(price * 100) / 100, label });
}
const prev = $('Check Products').isExecuted ? $('Check Products').last().json : null;
const attempt = prev ? prev.attempt + 1 : 1;
const lines = Number(s.form_lines);
const fields = [];
for (let i = 1; i <= lines; i++) {
  const pick = prev ? String(prev.raw['Product ' + i] ?? '') : '';
  const qty = prev ? prev.raw['Quantity ' + i] : null;
  fields.push({ fieldLabel: 'Product ' + i, fieldType: 'dropdown', requiredField: i === 1, fieldOptions: { values: (i === 1 ? [] : ['(none)']).concat(catalog.map((p) => p.label)).map((option) => ({ option })) },
    ...(catalog.some((p) => p.label === pick) ? { defaultValue: pick } : {}) });
  fields.push({ fieldLabel: 'Quantity ' + i, fieldType: 'number', requiredField: i === 1, placeholder: 'e.g. 1',
    ...(Number.isInteger(qty) && qty > 0 ? { defaultValue: String(qty) } : {}) });
}
fields.push({ fieldLabel: 'Notes (optional)', fieldType: 'textarea', placeholder: 'Anything we should know', ...(prev && prev.notes ? { defaultValue: prev.notes } : {}) });
const intro = 'Hello ' + c.customer_name + ', choose up to ' + lines + ' products and quantities. Prices are per unit, excluding ' + String(s.tax_label).trim() + '.';
const page_description = esc((prev ? 'Please fix: ' + prev.problems.join(' ') + ' (try ' + attempt + ' of 3)\n\n' : '') + intro);
return [{ json: { product_count: catalog.length, read_error: readError ? String(readError.message ?? readError).slice(0, 300) : '', catalog, attempt, form_fields: JSON.stringify(fields), page_description } }];

// Checks page two against the catalog the customer was shown. Prices are never taken from the form.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const s = $('Quote Settings').first().json;
const page = $('Build Products Page').last().json;
const f = $input.first().json;
const max = Number(s.max_quantity), lines = Number(s.form_lines);
const picked = [], problems = [], raw = {};
for (let i = 1; i <= lines; i++) {
  const label = String(f['Product ' + i] ?? '').trim();
  const q = f['Quantity ' + i];
  raw['Product ' + i] = label; raw['Quantity ' + i] = q;
  const noProduct = !label || label === '(none)';
  const noQty = q === null || q === undefined || q === '' || q === 0;
  if (noProduct) { if (!noQty) problems.push('Line ' + i + ': choose a product or clear the quantity.'); continue; }
  const p = page.catalog.find((x) => x.label === label);
  if (!p) { problems.push('Line ' + i + ': "' + label.slice(0, 80) + '" is not in our price list. Choose from the list.'); continue; }
  if (noQty) { problems.push('Line ' + i + ': enter a quantity from 1 to ' + max + ' for ' + p.name + '.'); continue; }
  const qty = Number(q);
  if (!Number.isInteger(qty) || qty < 1 || qty > max) { problems.push('Line ' + i + ': the quantity for ' + p.name + ' must be a whole number from 1 to ' + max + '.'); continue; }
  if (picked.some((l) => l.sku === p.sku)) { problems.push('Line ' + i + ': ' + p.name + ' is already on another line.'); continue; }
  picked.push({ sku: p.sku, name: p.name, unit: p.unit, unit_price: p.unit_price, quantity: qty });
}
const notes = String(f['Notes (optional)'] ?? '').replace(/\r\n?/g, '\n').replace(/[\u0000-\u0009\u000b-\u001f\u007f]/g, ' ').trim();
if (notes.length > 1000) problems.push('Notes are longer than 1000 characters.');
if (!picked.length && !problems.length) problems.push('Choose at least one product.');
return [{ json: { ok: problems.length === 0, problems, attempt: page.attempt, tries_left: page.attempt < 3, lines: picked, notes, raw,
  page_message: esc(problems.join('\n')) + '\n\nNothing was sent after 3 tries. Please open the form again.' } }];

// Reads the counter row and prepares a compare-and-set claim: the update only matches while last_number is still the value read here.
const msg = (e) => String(typeof e === 'string' ? e : e?.message ? e.message + (e.description ? ' (' + e.description + ')' : '') : JSON.stringify(e ?? 'unknown error')).slice(0, 500);
const rows = $input.all().map((i) => i.json);
const attempt = $runIndex + 1;
const err = rows.find((r) => r.error)?.error;
const valid = rows.filter((r) => r.id !== undefined).sort((a, b) => a.id - b.id);
let out = { attempt, can_claim: false, permanent: false };
if (err) out.reason = 'Reading the counter table failed: ' + msg(err);
else if (!valid.length) out = { ...out, permanent: true, reason: 'The counter table has no row. Execute "Run Once to Create Tables" or add a row with last_number 0.' };
else {
  const r = valid[0], seen = Number(r.last_number);
  if (r.last_number === null || r.last_number === '' || !Number.isInteger(seen) || seen < 0) out = { ...out, permanent: true, reason: 'last_number in counter row ' + r.id + ' must be a whole number of 0 or more.' };
  else out = { attempt, can_claim: true, permanent: false, counter_id: r.id, seen, next: seen + 1, token: $execution.id + '-' + attempt + '-' + Math.random().toString(36).slice(2, 10) };
}
return [{ json: out }];

// Waits 0.1 to 1 second (random, so colliding requests spread out) before reading the counter again.
// A Code pause is used instead of a Wait node: a Wait node pauses the execution, and a form page requested meanwhile can hang.
await new Promise((resolve) => setTimeout(resolve, 100 + Math.floor(Math.random() * 900)));
return $input.all();

// Prices every line from the catalog and the settings, in cents to avoid rounding drift. Dates use the workflow timezone.
const s = $('Quote Settings').first().json;
const c = $('Check Customer Details').first().json;
const p = $('Check Products').last().json;
const claim = $('Prepare Claim').last().json;
const rate = Number(s.tax_rate_percent);
const lines = p.lines.map((l) => ({ ...l, amount: Math.round(l.unit_price * 100) * l.quantity / 100 }));
const subtotalC = lines.reduce((t, l) => t + Math.round(l.amount * 100), 0);
const taxC = Math.round(subtotalC * rate / 100);
return [{ json: {
  quote_number: String(s.quote_prefix).trim() + String(claim.next).padStart(5, '0'), quote_seq: claim.next,
  customer_name: c.customer_name, customer_email: c.customer_email, company: c.company, notes: p.notes, lines,
  currency: String(s.currency).trim(), tax_label: String(s.tax_label).trim(), tax_rate: rate,
  subtotal: subtotalC / 100, tax: taxC / 100, total: (subtotalC + taxC) / 100,
  quote_date: $now.toISODate(), valid_until: $now.plus({ days: Number(s.validity_days) }).toISODate(),
} }];

// Renders the quote as index.html for Gotenberg. Every value is HTML-escaped, including settings.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const s = $('Quote Settings').first().json;
const q = $('Price the Quote').first().json;
const money = (v) => q.currency + ' ' + Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const rows = q.lines.map((l, i) => '<tr><td>' + (i + 1) + '</td><td>' + esc(l.name) + '<div class="sku">' + esc(l.sku) + '</div></td><td class="r">' + l.quantity + ' ' + esc(l.unit) + '</td><td class="r">' + esc(money(l.unit_price)) + '</td><td class="r">' + esc(money(l.amount)) + '</td></tr>').join('');
const html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>' + esc(q.quote_number) + '</title><style>'
  + 'body{font-family:Helvetica,Arial,sans-serif;color:#222;font-size:12px}h1{font-size:26px;margin:0;color:#1f3a5f}.top{display:flex;justify-content:space-between;margin-bottom:28px}'
  + '.muted{color:#666;white-space:pre-line}table{width:100%;border-collapse:collapse;margin-top:18px}th{background:#1f3a5f;color:#fff;text-align:left;padding:8px}'
  + 'td{padding:8px;border-bottom:1px solid #ddd;vertical-align:top}.r{text-align:right}.sku{color:#888;font-size:10px}.tot td{border:none}.grand td{font-weight:bold;font-size:14px;border-top:2px solid #1f3a5f}'
  + '.box{margin-top:22px;padding:10px;background:#f4f6f9;white-space:pre-line}</style></head><body>'
  + '<div class="top"><div><h1>' + esc(s.business_name) + '</h1><div class="muted">' + esc(s.business_details) + '</div></div>'
  + '<div class="r"><h1>Quote</h1><div>' + esc(q.quote_number) + '</div><div>Date: ' + esc(q.quote_date) + '</div><div>Valid until: ' + esc(q.valid_until) + '</div></div></div>'
  + '<div><b>For</b><br>' + esc(q.customer_name) + '<br>' + esc(q.company) + '<br>' + esc(q.customer_email) + '</div>'
  + '<table><tr><th>#</th><th>Product</th><th class="r">Quantity</th><th class="r">Unit price</th><th class="r">Amount</th></tr>' + rows
  + '<tr class="tot"><td colspan="4" class="r">Subtotal</td><td class="r">' + esc(money(q.subtotal)) + '</td></tr>'
  + '<tr class="tot"><td colspan="4" class="r">' + esc(q.tax_label) + ' ' + q.tax_rate + '%</td><td class="r">' + esc(money(q.tax)) + '</td></tr>'
  + '<tr class="grand"><td colspan="4" class="r">Total</td><td class="r">' + esc(money(q.total)) + '</td></tr></table>'
  + (q.notes ? '<div class="box"><b>Your notes</b>\n' + esc(q.notes) + '</div>' : '')
  + '<div class="box">' + esc(s.quote_terms) + '\nThis quote is valid until ' + esc(q.valid_until) + '.</div></body></html>';
return [{ json: { quote_number: q.quote_number }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' } } }];

// Decides the quote status from what happened to the PDF and the email, and writes the customer's result page.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const msg = (e) => String(typeof e === 'string' ? e : e?.message ? e.message + (e.description ? ' (' + e.description + ')' : '') : JSON.stringify(e ?? 'unknown error')).slice(0, 500);
const s = $('Quote Settings').first().json;
const q = $('Price the Quote').first().json;
const it = $input.first();
const owner = String(s.owner_email).trim().toLowerCase();
let status = 'failed', detail, stage = 'pdf';
if ($('Email Quote to Customer').isExecuted) {
  stage = 'email';
  if (it.json.error) detail = 'The quote email could not be sent: ' + msg(it.json.error);
  else {
    const rejected = (it.json.rejected || []).map((x) => String(x).toLowerCase());
    if (rejected.includes(q.customer_email)) detail = 'The mail server rejected the customer address ' + q.customer_email + (rejected.includes(owner) ? '.' : '; the blind copy to ' + owner + ' was accepted.');
    else { status = 'sent'; detail = 'Emailed to ' + q.customer_email + (rejected.includes(owner) ? '; the copy to ' + owner + ' was rejected.' : ' with a copy to ' + owner + '.'); }
  }
} else if (it.json.error) detail = 'Gotenberg could not create the PDF: ' + msg(it.json.error);
else detail = 'Gotenberg answered without a PDF (content type ' + (it.binary?.data?.mimeType || 'none') + '). Check gotenberg_url.';
const total = q.currency + ' ' + Number(q.total).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const page = status === 'sent'
  ? { page_title: 'Your quote is on its way', page_message: 'Thank you, ' + esc(q.customer_name) + '. Quote ' + esc(q.quote_number) + ' (total ' + esc(total) + ', valid until ' + esc(q.valid_until) + ') has been emailed to ' + esc(q.customer_email) + '.' }
  : stage === 'pdf'
    ? { page_title: 'Quote registered, PDF delayed', page_message: 'Thank you, ' + esc(q.customer_name) + '. Your request is saved as quote ' + esc(q.quote_number) + ', but the PDF could not be created right now. We have been told and will email it to ' + esc(q.customer_email) + ' as soon as possible.' }
    : { page_title: 'Quote created, email not sent', page_message: 'Thank you, ' + esc(q.customer_name) + '. Quote ' + esc(q.quote_number) + ' was created, but we could not email it to ' + esc(q.customer_email) + '. We have been told and will send it to you as soon as possible.' };
return [{ json: { status, detail, stage, ...page } }];

// One alert email for every failure, and the honest page the customer sees.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const msg = (e) => String(typeof e === 'string' ? e : e?.message ? e.message + (e.description ? ' (' + e.description + ')' : '') : JSON.stringify(e ?? 'unknown error')).slice(0, 500);
const s = $('Quote Settings').first().json;
const ran = (name) => $(name).isExecuted;
const c = ran('Check Customer Details') ? $('Check Customer Details').first().json : {};
const it = $input.first().json;
const unavailable = { page_title: 'Quotes are unavailable right now', page_message: 'Online quotes cannot be created at the moment. We have been told about it. Please try again later.' };
const notCreated = { page_title: 'We could not create your quote', page_message: 'Thank you, ' + esc(c.customer_name) + '. Something went wrong on our side and no quote was created. We have been told about it and will contact you at ' + esc(c.customer_email) + '.' };
let subject, problem, quote = null, page, page_expired = false;
if (it.form_fields !== undefined && it.product_count > 0) {
  // Page two (Choose Products) reached its time limit without being submitted. Nobody is waiting for a result page.
  page_expired = true;
  problem = 'Page 2 (products) was not submitted within its time limit (24 hours as shipped), so no quote was created. Contact the customer if you want to follow up.';
  subject = 'Quote request from ' + c.customer_email + ' not finished: page 2 not submitted';
  page = { page_title: 'nothing (page 2 expired; a late submit only shows n8n\'s own "Your response has been recorded")', page_message: '' };
} else if (ran('Record Outcome')) {
  const o = $('Record Outcome').first().json;
  quote = $('Price the Quote').first().json;
  const saved = it.id !== undefined && !it.error;
  const parts = [];
  if (o.status !== 'sent') parts.push(o.detail);
  if (!saved) parts.push('The quote row could not be set to "' + o.status + '": ' + (it.error ? msg(it.error) : 'the data table returned no updated row (was the row deleted or a column removed?)') + '.');
  problem = parts.join(' ');
  subject = o.status === 'sent' ? 'Quote ' + quote.quote_number + ' sent, but its status was not saved' : 'Quote ' + quote.quote_number + ' NOT sent to ' + quote.customer_email;
  page = { page_title: o.page_title, page_message: o.page_message };
} else if (ran('Save Quote')) {
  quote = $('Price the Quote').first().json;
  problem = 'Quote number ' + quote.quote_number + ' was claimed, but the quote could not be saved: ' + (it.error ? msg(it.error) : 'the data table returned no saved row (was a column removed?).') + ' No PDF or email was sent; the number stays unused.';
  subject = 'Quote request from ' + c.customer_email + ' could not be saved';
  page = notCreated;
} else if (ran('Prepare Claim')) {
  const p = $('Prepare Claim').last().json;
  const claimErr = ran('Claim Quote Number') ? $('Claim Quote Number').last().json.error : null;
  problem = 'No quote number could be claimed after ' + p.attempt + ' tries. ' + (p.reason || (claimErr ? 'Last error: ' + msg(claimErr) : 'The counter row never matched: other requests kept changing it, or a counter column (last_number, claim_token) is missing.'));
  subject = 'Quote request from ' + c.customer_email + ' got no quote number';
  page = notCreated;
} else if (ran('Build Products Page')) {
  const b = $('Build Products Page').last().json;
  problem = b.read_error ? 'Reading the catalog table failed: ' + b.read_error : 'The catalog has no active product with a sku, name and unit_price, so the form cannot offer anything.';
  subject = b.read_error ? 'Quote form unavailable: catalog not readable' : 'Quote form unavailable: no products';
  page = unavailable;
} else {
  problem = $('Check Setup').first().json.problems.join(' ');
  subject = 'Quote form unavailable: setup problem';
  page = unavailable;
}
const row = (k, v) => '<tr><td><b>' + esc(k) + '</b></td><td>' + esc(v) + '</td></tr>';
const lines = page_expired ? '' : quote ? quote.lines.map((l) => l.quantity + ' x ' + l.name + ' (' + l.sku + ')').join('; ') : ($('Check Products').isExecuted ? $('Check Products').last().json.lines.map((l) => l.quantity + ' x ' + l.name).join('; ') : '');
const html = '<p>' + esc(problem) + '</p><table border="1" cellpadding="4" cellspacing="0">'
  + (c.customer_email ? row('Customer', c.customer_name + ', ' + c.company + ' <' + c.customer_email + '>') : '')
  + (quote ? row('Quote', quote.quote_number + ', ' + quote.currency + ' ' + quote.total.toFixed(2) + ', valid until ' + quote.valid_until) : '')
  + (lines ? row('Lines', lines) : '')
  + row('Customer was shown', page.page_title)
  + row('Execution', $execution.id) + '</table>';
return [{ json: { subject, problem, html, page_expired, ...page } }];
